 return f'''<!doctype html><html lang="en-CA"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(desc)}"><meta name="theme-color" content="#102c3b"><link rel="canonical" href="https://highdusting.ca{path}"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(desc)}"><meta property="og:type" content="website"><meta property="og:image" content="https://highdusting.ca/assets/hero.webp"><link rel="icon" href="/favicon.svg?v=industrial-seal" type="image/svg+xml"><link rel="preload" href="/assets/hero.webp" as="image"><link rel="stylesheet" href="/styles.css"><script type="application/ld+json">{json.dumps(schema)}</script><script src="/formspree.js" defer></script><script src="/app.js" defer></script></head><body>{header()}<main id="main">{content}</main>{footer()}</body></html>'''
